tool.command:

  ln -f -s ${input_pdb_path} ${input_pdb_path}_`echo $$`.${input_pdb_path.ext};

  ln -f -s ${input_active_list_path} ${input_active_list_path}_`echo $$`.${input_active_list_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

haddock3_passive_from_active

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__active_list__dq__:__dq__${properties.active_list}__dq__,__dq__chain_id__dq__:__dq__${properties.chain_id}__dq__,__dq__surface_list_path__dq__:__dq__${properties.surface_list_path}__dq__,__dq__radius__dq__:${properties.radius},__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_pdb_path) != 'None':
    --input_pdb_path ${input_pdb_path}_`echo $$`.${input_pdb_path.ext}
  #end if

  #if str($input_active_list_path) != 'None':
    --input_active_list_path ${input_active_list_path}_`echo $$`.${input_active_list_path.ext}
  #end if


  --output_actpass_path $outname_output_actpass_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_pdb_path}_`echo $$`.${input_pdb_path.ext};

  rm -f ${input_active_list_path}_`echo $$`.${input_active_list_path.ext};


  if test -f $outname_output_actpass_path; then mv $outname_output_actpass_path $output_actpass_path; fi;
